python3 -c '
import itertools, json, shlex, subprocess, sys
from pathlib import Path

def emit(decision, reason=""):
    out = {"decision": decision}
    if reason:
        out["reason"] = reason
    print(json.dumps(out))
    sys.exit(0)

def is_protected(branch):
    return branch in {"main", "develop"} or branch.startswith("release/")

def branch_of(repo_dir):
    if not repo_dir:
        return ""
    for argv in (["git", "symbolic-ref", "--short", "HEAD"], ["git", "rev-parse", "--abbrev-ref", "HEAD"]):
        try:
            res = subprocess.run(argv, cwd=repo_dir, capture_output=True, text=True, timeout=3)
            if res.returncode == 0 and res.stdout.strip():
                return res.stdout.strip()
        except Exception:
            return ""
    return ""

try:
    payload = json.load(sys.stdin)
except Exception:
    emit("allow")

args = (payload.get("toolCall") or {}).get("args") or {}
cmd = args.get("CommandLine") or args.get("command") or ""
cwd = payload.get("cwd") or ""
if not isinstance(cmd, str) or "git" not in cmd:
    emit("allow")

try:
    lx = shlex.shlex(cmd, posix=True, punctuation_chars=";&|\n")
    lx.whitespace = " \t\r"
    lx.whitespace_split = True
    lx.commenters = ""
    toks = list(lx)
except ValueError:
    emit("allow")

ops = {";", "&&", "||", "|", "&", "\n"}
val_flags = {"-C", "-c", "--git-dir", "--work-tree", "--namespace", "--config-env"}
cur_cwd = cwd
for is_op, grp in itertools.groupby(toks, key=lambda t: t in ops):
    if is_op:
        continue
    seg = list(grp)
    while seg and "=" in seg[0] and not seg[0].startswith("-"):
        seg.pop(0)
    if not seg:
        continue
    if seg[0] == "cd" and len(seg) >= 2 and not seg[1].startswith("-"):
        cand = Path(seg[1]).expanduser()
        cur_cwd = str(cand if cand.is_absolute() or not cur_cwd else Path(cur_cwd) / cand)
        continue
    if Path(seg[0]).name != "git":
        continue
    git_dir = cur_cwd
    i = 1
    while i < len(seg) and seg[i].startswith("-"):
        if seg[i] == "-C" and i + 1 < len(seg):
            cand = Path(seg[i + 1]).expanduser()
            git_dir = str(cand if cand.is_absolute() or not cur_cwd else Path(cur_cwd) / cand)
            i += 2
        elif seg[i] in val_flags and i + 1 < len(seg):
            i += 2
        else:
            i += 1
    if i >= len(seg):
        continue
    sub, rest = seg[i], seg[i + 1:]
    if sub == "commit":
        b = branch_of(git_dir)
        if is_protected(b):
            emit("deny", f"Direct git commit on protected branch {b} is blocked by Coder Nexus Git Flow rules. Switch to a work branch (feature/*, fix/*, refactor/*, hotfix/*) first.")
    elif sub == "push":
        if "--all" in rest or "--tags" in rest:
            emit("deny", "Blocked by Coder Nexus Git Flow rules: do not use git push --all or git push --tags. Push explicit refs instead.")
        forced = any(a in {"--force", "--force-with-lease"} or a.startswith("--force-with-lease=") or (a.startswith("-") and not a.startswith("--") and "f" in a[1:]) for a in rest)
        if forced:
            pos = [a for a in rest if not a.startswith("-")]
            refs = pos[1:] if len(pos) >= 2 else []
            targets = []
            for ref in refs:
                t = ref.split(":", 1)[-1].lstrip("+")
                if t.startswith("refs/heads/"):
                    t = t[11:]
                if t in ("HEAD", ""):
                    t = branch_of(git_dir)
                targets.append(t)
            if not targets:
                targets = [branch_of(git_dir)]
            for t in targets:
                if is_protected(t):
                    emit("deny", f"Force-pushing protected branch {t} is blocked by Coder Nexus Git Flow rules.")
emit("allow")
'
